__NUXT_JSONP__("/jp/contact/thanks", (function(a){return {data:[{details:{slug:"jp",pageTitle:"お問い合わせありがとうございます | Mentor Language Institute",pageDescription:a,title:"お問い合わせありがとうございます",subtitle:[a,"現在、アメリカへの留学手続きはとても複雑なため、お問合せ・資料請求をご希望頂いた方へひとりひとりお電話にて手続きや当校についてのご説明をさせて頂いております。","もし、電話による説明を希望されなかった場合を除き、頂いた問合せ内容の回答も含め、事務局スタッフよりお電話させて頂きますので、予めお見知りおき頂ければ幸いです。","どうぞよろしくお願いいたします。","\u003Ca href=\"\u002Fjp\"\u003Eトップページへ戻る\u003C\u002Fa\u003E"],dir:"\u002Fcontact-thanks",path:"\u002Fcontact-thanks\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:28.996Z",updatedAt:"2025-05-26T12:06:27.724Z"}}],fetch:{},mutations:void 0}}("MLIへのお問い合わせ誠にありがとうございます。")));